'use strict';

const path = require('node:path');
const { UPGRADE_DIR, REPORT_FILE } = require('./constants');
const { createContext } = require('./context');
const { runPreflight } = require('./preflight');
const { runRewrite } = require('./steps/rewrite');
const { runRemovals } = require('./steps/removals');
const { runVerify } = require('./steps/verify');
const { runInstall } = require('./steps/install');
const { analyze, printSummary } = require('./steps/analyze');
const { runOpenRewrite } = require('./steps/openrewrite');
const { generate } = require('./steps/analyze/reporter');

async function upgrade(options = {}) {
  const cds = require('../../lib/cds');
  const { error } = require('../../lib/util/term');

  console.log();
  try {
    cds.root = path.resolve(process.cwd(), '.');
    await cds.plugins;
    cds.env = cds.env.for('cds', cds.root);

    const ctx = createContext(options);

    const pre = await runPreflight(ctx, cds);
    if (!pre.ok) {
      process.exitCode = 1;
      return;
    }

    const rewriteResult = await runRewrite(ctx, cds);
    if (rewriteResult.aborted) {
      if (rewriteResult.reason === 'non-tty') process.exitCode = 1;
      return;
    }

    await runRemovals(ctx, cds);
    await runVerify(ctx, cds);
    await runInstall(ctx, cds);

    if (ctx.project.isJava && ctx.shouldFix) {
      await runOpenRewrite(ctx);
    }

    await analyze(ctx);
    printSummary(ctx);
    await generate(ctx);

    console.log();
    if (ctx.shouldReport) {
      console.log(`Review ${UPGRADE_DIR}/${REPORT_FILE} for remaining code changes.`);
    } else {
      console.log(`Re-run with --report to write ${UPGRADE_DIR}/${REPORT_FILE} listing remaining code changes.`);
    }
    console.log();
  } catch (e) {
    console.log();
    console.log(error(e.message || e));
    throw e;
  }
}

module.exports = upgrade;
